-- Cata+ quest currency rewards. Same entry+build key convention as quest_properties.
CREATE TABLE IF NOT EXISTS `quest_properties_currencies` (
  `entry` int unsigned NOT NULL DEFAULT '0',
  `build` smallint NOT NULL DEFAULT '12340',
  `RewardCurrencyId1` int unsigned NOT NULL DEFAULT '0',
  `RewardCurrencyId2` int unsigned NOT NULL DEFAULT '0',
  `RewardCurrencyId3` int unsigned NOT NULL DEFAULT '0',
  `RewardCurrencyId4` int unsigned NOT NULL DEFAULT '0',
  `RewardCurrencyCount1` int unsigned NOT NULL DEFAULT '0',
  `RewardCurrencyCount2` int unsigned NOT NULL DEFAULT '0',
  `RewardCurrencyCount3` int unsigned NOT NULL DEFAULT '0',
  `RewardCurrencyCount4` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`entry`,`build`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Quest currency rewards (Cata+)';



